// Text side of the decoder questions, ported from marimba-audio 0.1.2 (lexical.py, language.py, the vendored qwen_asr utils):
// term normalisation, repetition collapse, parse of the model's output, and decoding of token ids without a tokenizer library.
// Pure functions; the conformance fixtures were generated by the Python originals (test/fixtures/media/decoder-text.json).

// Canonical combining class != 0 (Python unicodedata.combining, Unicode 14.0), as code point ranges in hex.
const CCC = "300-34e,350-36f,483-487,591-5bd,5bf,5c1-5c2,5c4-5c5,5c7,610-61a,64b-65f,670,6d6-6dc,6df-6e4,6e7-6e8,6ea-6ed,711,730-74a,7eb-7f3,7fd,816-819,81b-823,825-827,829-82d,859-85b,898-89f,8ca-8e1,8e3-8ff,93c,94d,951-954,9bc,9cd,9fe,a3c,a4d,abc,acd,b3c,b4d,bcd,c3c,c4d,c55-c56,cbc,ccd,d3b-d3c,d4d,dca,e38-e3a,e48-e4b,eb8-eba,ec8-ecb,f18-f19,f35,f37,f39,f71-f72,f74,f7a-f7d,f80,f82-f84,f86-f87,fc6,1037,1039-103a,108d,135d-135f,1714-1715,1734,17d2,17dd,18a9,1939-193b,1a17-1a18,1a60,1a75-1a7c,1a7f,1ab0-1abd,1abf-1ace,1b34,1b44,1b6b-1b73,1baa-1bab,1be6,1bf2-1bf3,1c37,1cd0-1cd2,1cd4-1ce0,1ce2-1ce8,1ced,1cf4,1cf8-1cf9,1dc0-1dff,20d0-20dc,20e1,20e5-20f0,2cef-2cf1,2d7f,2de0-2dff,302a-302f,3099-309a,a66f,a674-a67d,a69e-a69f,a6f0-a6f1,a806,a82c,a8c4,a8e0-a8f1,a92b-a92d,a953,a9b3,a9c0,aab0,aab2-aab4,aab7-aab8,aabe-aabf,aac1,aaf6,abed,fb1e,fe20-fe2f,101fd,102e0,10376-1037a,10a0d,10a0f,10a38-10a3a,10a3f,10ae5-10ae6,10d24-10d27,10eab-10eac,10f46-10f50,10f82-10f85,11046,11070,1107f,110b9-110ba,11100-11102,11133-11134,11173,111c0,111ca,11235-11236,112e9-112ea,1133b-1133c,1134d,11366-1136c,11370-11374,11442,11446,1145e,114c2-114c3,115bf-115c0,1163f,116b6-116b7,1172b,11839-1183a,1193d-1193e,11943,119e0,11a34,11a47,11a99,11c3f,11d42,11d44-11d45,11d97,16af0-16af4,16b30-16b36,16ff0-16ff1,1bc9e,1d165-1d169,1d16d-1d172,1d17b-1d182,1d185-1d18b,1d1aa-1d1ad,1d242-1d244,1e000-1e006,1e008-1e018,1e01b-1e021,1e023-1e024,1e026-1e02a,1e130-1e136,1e2ae,1e2ec-1e2ef,1e8d0-1e8d6,1e944-1e94a";
const CCC_RANGES: [number, number][] = CCC.split(",").map((r) => { const [a, b] = r.split("-"); return [parseInt(a, 16), parseInt(b ?? a, 16)]; });

export function combining(cp: number): boolean {
  let lo = 0, hi = CCC_RANGES.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1, [a, b] = CCC_RANGES[mid];
    if (cp < a) hi = mid - 1; else if (cp > b) lo = mid + 1; else return true;
  }
  return false;
}

/**
 * Python str.casefold, approximated per character by upper-then-lower case (exact for the full foldings that matter: ß -> ss, ς -> σ, ſ -> s, ...).
 * Per character, because lower-casing a whole word turns a final Σ into ς. Two scripts fold the other way and are handled by hand:
 * dotless ı stays, capital ẞ is "ss", Cherokee folds to upper case.
 */
export function casefold(s: string): string {
  let out = "";
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (cp === 0x1e9e) out += "ss";
    else if (cp === 0x131 || (cp >= 0x13a0 && cp <= 0x13f5)) out += ch;
    else if (cp >= 0xab70 && cp <= 0xabbf) out += String.fromCodePoint(cp - 0xab70 + 0x13a0);
    else if (cp >= 0x13f8 && cp <= 0x13fd) out += String.fromCodePoint(cp - 8);
    else out += ch.toUpperCase().toLowerCase();
  }
  return out;
}

/** lexical.normalize: casefold, NFKD, drop combining marks, runs of non-alphanumeric characters (and "_") become one space. */
export function normalizeTerm(text: string): string {
  const decomposed = casefold(text).normalize("NFKD");
  let out = "";
  for (const ch of decomposed) if (!combining(ch.codePointAt(0)!)) out += ch;
  return out.replace(/[^\p{L}\p{N}]+|_+/gu, " ").split(" ").filter(Boolean).join(" ");
}

/** exact_fraction for one hypothesis: the normalised term occurs as whole words in the normalised text. */
export function containsTerm(target: string, text: string): boolean {
  return (" " + normalizeTerm(text) + " ").includes(" " + target + " ");
}

/** Fraction of the hypotheses that contain the term (lexical.exact_fraction). */
export function termFraction(term: string, hypotheses: string[]): number {
  const target = normalizeTerm(term);
  if (!target || !hypotheses.length) throw new Error("a term with letters or digits and at least one hypothesis are required");
  return hypotheses.filter((h) => containsTerm(target, h)).length / hypotheses.length;
}

// ---- qwen_asr utils: detect_and_fix_repetitions, parse_asr_output (operate on code points, as Python strings do) ------------------

const cpEq = (s: string[], a: number, b: number, k: number): boolean => {
  for (let i = 0; i < k; i++) if (s[a + i] !== s[b + i]) return false;
  return true;
};

function fixCharRepeats(s: string[], thresh: number): string[] {
  const res: string[] = [];
  let i = 0;
  const n = s.length;
  while (i < n) {
    let count = 1;
    while (i + count < n && s[i + count] === s[i]) count++;
    if (count > thresh) res.push(s[i]); else for (let j = 0; j < count; j++) res.push(s[i]);
    i += count;
  }
  return res;
}

function fixPatternRepeats(s: string[], thresh: number, maxLen = 20): string[] {
  const n = s.length, minRepeat = thresh * 2;
  if (n < minRepeat) return s;
  let i = 0, found = false;
  const result: string[] = [];
  while (i <= n - minRepeat) {
    for (let k = 1; k <= maxLen; k++) {
      if (i + k * thresh > n) break;
      let valid = true;
      for (let rep = 1; rep < thresh; rep++) {
        const st = i + rep * k;
        // Python compares slices s[st:st+k] and s[i:i+k]; a short slice at the end of s never equals a full one.
        if (st + k > n || !cpEq(s, st, i, k)) { valid = false; break; }
      }
      if (valid) {
        let end = i + thresh * k;
        while (end + k <= n && cpEq(s, end, i, k)) end += k;
        result.push(...s.slice(i, i + k));
        result.push(...fixPatternRepeats(s.slice(end), thresh, maxLen));
        i = n; found = true;
        break;
      }
    }
    if (found) break;
    result.push(s[i]);
    i++;
  }
  if (!found) result.push(...s.slice(i));
  return result;
}

export function detectAndFixRepetitions(text: string, threshold = 20): string {
  return fixPatternRepeats(fixCharRepeats(Array.from(text), threshold), threshold).join("");
}

const WS = "[\\t\\n\\v\\f\\r \\x1c-\\x1f\\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]";
/** Python str.strip() (Unicode whitespace; unlike \\s, not U+FEFF). */
const pyStrip = (s: string) => s.replace(new RegExp(`^${WS}+|${WS}+$`, "g"), "");

/** parse_asr_output(raw)[1]: the transcript after "<asr_text>" (or the whole text when the tag is missing). */
export function parseAsrText(raw: string): string {
  const s0 = pyStrip(raw ?? "");
  if (!s0) return "";
  const s = detectAndFixRepetitions(s0);
  const at = s.indexOf("<asr_text>");
  if (at < 0) return pyStrip(s);
  return pyStrip(s.slice(at + "<asr_text>".length));
}

// ---- byte-level BPE decoding ----------------------------------------------------------------------------------------------------

export interface DecoderTokens { tokens: string[]; added: number[]; special: number[] }

let BYTE_OF: Map<string, number> | null = null;
function byteOf(): Map<string, number> {
  if (BYTE_OF) return BYTE_OF;
  // GPT-2 byte <-> unicode table
  const bs: number[] = [];
  for (let b = 33; b <= 126; b++) bs.push(b);
  for (let b = 161; b <= 172; b++) bs.push(b);
  for (let b = 174; b <= 255; b++) bs.push(b);
  const cs = bs.slice();
  let n = 0;
  for (let b = 0; b < 256; b++) if (!bs.includes(b)) { bs.push(b); cs.push(256 + n); n++; }
  BYTE_OF = new Map(bs.map((b, i) => [String.fromCodePoint(cs[i]), b]));
  return BYTE_OF;
}

/** decode(ids, skip_special_tokens=True, clean_up_tokenization_spaces=False) of the Qwen2 byte-level tokenizer. */
export function decodeIds(ids: number[], t: DecoderTokens): string {
  const table = byteOf(), special = new Set(t.special), added = new Set(t.added);
  let out = "", bytes: number[] = [];
  const flush = () => { if (bytes.length) { out += new TextDecoder("utf-8").decode(Uint8Array.from(bytes)); bytes = []; } };
  for (const id of ids) {
    if (special.has(id)) continue;
    const piece = t.tokens[id] ?? "";
    if (added.has(id)) { flush(); out += piece; continue; }
    for (const ch of piece) { const b = table.get(ch); if (b === undefined) throw new Error(`token ${id}: character ${JSON.stringify(ch)} is not a byte-level piece`); bytes.push(b); }
  }
  flush();
  return out;
}
